<template lang="en">
<div class="my-popups">
    <div class="modal d-block">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <loader :is-visible="isLoading"></loader>

                <div class="modal-header theme-primary partition-full  d-flex">
                    <h4 class="modal-title">{{ $t('DeployProductLocationWise') }}</h4>

                    <button type="button" class="close" v-on:click="ClosePopup">
                        <em class="fa fa-times" aria-hidden="true"></em>
                    </button>

                    <span class="user-guide ">
                        <a class="ancuserguide text-white" data-toggle="collapse" href="#collapseReplyUG" role="button" aria-expanded="false" aria-controls="collapseExample"> <em class="fa fa-files-o pr-2"></em>User Guide</a>
                        <div id="collapseReplyUG" class="divancuserguide collapse overflow-auto">
                            <div id="scrollbarreplyuserguideMangeView" class="custom-scrollbar-js">
                                <div class="con" v-html="$t('useguideforRelatedInformation').replace(/\\n/g, '')"></div>
                            </div>
                        </div>
                    </span>

                </div>
                <div class="modal-body">
                    <Form ref="AddDeploy" autocomplete="off">
                        <div class="col-md-12">
                            <div class="form-group">
                                <div class="listing OuterMainDiv">
                                    <div class="row">

                                        <dynamic-form :lang="$i18n.locale" ref="AddDeployProduct" :buttons="buttons" :schema="FormSchema" v-on:OnSubmit="onSubmit">

                                        </dynamic-form>

                                    </div>
                                </div>
                            </div>
                        </div>
                    </Form>
                </div>

                <div v-if="arryaofData.length > 0" class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left px-0 m-2">
                    <div class="row flex-row-reverse m-0">
                        <div class="col-lg-4 text-right">

                            <a href="javascript:;" v-on:click="SubmitData()" class="btn btn-success formbtn text-white mr-1" :title="$t('Save')"><i class="fa fa-save pr-2"></i>
                                <span>{{ $t('Save') }}</span></a>
                            <a href="javascript:;" @click="ClosePopup()" :title="$t('Cancel')" class="btn btn-danger formbtn text-white"><i class="fa fa-close pr-2"></i><span>{{
                                        $t('Cancel') }}</span></a>
                        </div>

                    </div>
                </div>
            </div>
        </div>
    </div>
</div>
</template>

<script>
import DataService from '../../service/DataService';
// import { TreeSelectField } from 'tg-controls_cli/dist/myLib.common'
import Treeselect from '@riophae/vue-treeselect';
import '@riophae/vue-treeselect/dist/vue-treeselect.css'
export default {
    components: {
        'tree-view': Treeselect
    },
    props: {
        ClickType: {
            type: String
        },
        AsseCatalogtId: {
            type: String
        },
        DeployItemId: {
            type: String
        }
    },

    data() {
        return {
            isLoading: false,
            arryaofData: [],
            LocationData: [],
            treeViewDisabled: true,
            options: [],
            isEdit: true,
            dData: [],
            fileMulitpleData: [],
            AllowedFileType: [],
            acceptArray: [],
            TreeValue: null,
            parentChildOptions: [],
            // StaticObj: [
            //{
            // layoutType: "single",
            // Data: [
            // {
            // astype: "TreeSelectField",
            // label: this.$t('Location'),
            // name: "Location",
            //value: null,
            //placeholder: "Select Location",
            //config: {
            //options: [],
            //showAddIcon: true

            //},
            //validationRules: {
            // "required": true
            //},
            //},
            //]
            // },
            // ],
            FormSchema: [

            ],
            attachmentsArray: [],

            buttons: [{
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                },
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    isVisible: true,
                    onClick: this.ClosePopup
                }

            ],

            DataLoaded: 0,
            LocationName: '',
            noRecord: false,
            ownershiptypevalue: 0,

        };
    },
    created: async function () {
        //debugger;
        var vm = this;
        await vm.GetAllowFileType();
        await vm.getForm(vm.DeployItemId);

        // vm.DataLoaded = 1;
    },
    methods: {
        GetLocationByCompanyId: async function () {
            //debugger;
            var vm = this;
            var url = `reqForm=assetassignment`
            await DataService.GetLocationByuserId(url).then(response => {
                vm.parentChildOptions = [];
                //if ((typeof (vm.$route.params.reqForm) != 'undefined') && (vm.$route.params.reqForm != 'pendingRequest' || vm.GetParentDetails == '' || vm.GetParentDetails == null)) {
                vm.TreeValue = response.data.data[0].COMPANY_LOCATION_ID;
                //} else {
                //vm.TreeValue = null;
                //}
                response.data.data.forEach((value) => {
                    var CheckIfExist = vm.parentChildOptions.filter(function (el) {
                        return el.COMPANY_LOCATION_ID == value.COMPANY_LOCATION_ID;
                    });
                    if (CheckIfExist.length == 0) {
                        if (value.PARENT_LOCATION_ID == null) {
                            let locationId = value.COMPANY_LOCATION_ID
                            let rslt = vm.getChildLocation(locationId, value, response.data.data)
                            vm.parentChildOptions.push(rslt)
                        }
                    }
                });
                vm.$refs.setuplocation.UpdateKeyValue();
            });
        },
        getChildLocation: function (locationId, currentItem, data) {
            let ths = this;
            let treeArray = {};
            treeArray = {
                id: currentItem.COMPANY_LOCATION_ID,
                label: currentItem.LOCATION_NAME
            }
            let retrunArray = treeArray;
            var childArray = data.filter(function (el) {
                return el.PARENT_LOCATION_ID == locationId;
            });
            let finalChildArray = [];
            childArray.forEach((value) => {
                let ChildfolderId = value.COMPANY_LOCATION_ID
                var CheckIfExist1 = finalChildArray.filter(function (el) {
                    return el.COMPANY_LOCATION_ID == value.COMPANY_LOCATION_ID;
                });
                if (CheckIfExist1.length == 0) {
                    var CheckIfExist = data.filter(function (el) {
                        return el.PARENT_LOCATION_ID == ChildfolderId;
                    });
                    if (CheckIfExist != null && CheckIfExist.length > 0) {
                        let rslt = ths.getChildLocation(ChildfolderId, value, data);
                        finalChildArray.push(rslt);
                    } else {
                        treeArray = {
                            id: `${value.COMPANY_LOCATION_ID}`,
                            label: `${value.LOCATION_NAME}`
                        }
                        finalChildArray.push(treeArray);
                    }
                }
            });
            retrunArray.children = finalChildArray;
            return retrunArray;
        },
        async GetAllowFileType() {
            var vm = this;
            await DataService.GetAllowFileType().then((response) => {

                if (response.data != null) {
                    const AllowedFileTypes = response.data.AllowedFileTypes.split(',');

                    AllowedFileTypes.forEach(fileType => {
                        // Remove dots from file types
                        const fileTypeWithoutDot = fileType.trim().replace(/\./g, ''); // Remove dots and trim whitespace

                        vm.acceptArray.push({
                            fileType: fileTypeWithoutDot,
                            iconClass: 'fa-file-image-o'
                        });
                    });
                }

            });

        },
        ClosePopup() {

            var vm = this;
            //   vm.$parent.;
            vm.$parent.DeployClosePOp();

        },
        getForm: async function (id) {
            // debugger;

            var vm = this;
            vm.isLoading = true;
            var url = `recordId=${id}&moduleName=Asset&subModuleCode=DEPLOY_PRODUCT&usefor=Add`;
            await DataService.GetDynamicForm(url).then(function (response) {

