                            if (row.CORE_CONFIG_KEY == "TicketDisallowedFileTypes") {
                                vm.AllowedFileType = row.CONFIG_DATA_VALUE;

                            }
                        });
                    }

                    var assetData = response.data.data;
                    // console.log("Response :",response.data.data)
                    //console.log("AssetDeployCatalogueDetails[0]",response.data.AssetDeployCatalogueDetails)
                    vm.FormSchema = vm.$refs.AddDeployProduct.ConvertCustomFieldIntoDynamicFormObj(response.data.data);
                    console.log("", )

                    vm.FormSchema.forEach((group, gi) => {

                        group.Data.forEach((field, fi) => {
                            let ownershiptype = 0;
                            //debugger;
                            // if (field.name == "location") {

                            // field.config.showAddIcon = true;

                            //field.astype = 'SlotField';

                            //vm.GetLocationByCompanyId();

                            // vm.TreeValue = field.value ? field.value : null;

                            //var options = field.config.options;
                            //vm.parentChildOptions = [];
                            //options.forEach((op) => {
                            //var CheckIfExist = vm.parentChildOptions.filter(function (el) {
                            // el.value == op.value;
                            //});
                            //if (CheckIfExist.length == 0) {
                            //if (op.first_value == null) {
                            //let locationId = op.value
                            //let rslt = vm.getChildLocation(locationId, op, options)
                            //vm.parentChildOptions.push(rslt)
                            //}
                            //}
                            //});

                            //}
                            if (field.name == "location") {
                                if (vm.DeployItemId > 0) {
                                    field.disabled = true;
                                } else {
                                    field.disabled = false;

                                }
                            }

                            if (vm.DeployItemId == 0) {

                                const hiddenFields111 = ["rent_start_date", "rent_end_date", "rent_rate", "rent_period", "rent_file", "lease_start_date", "lease_end_date", "lease_cost", "lease_period", "lease_file", "lease_type"];

                                if (hiddenFields111.includes(field.name)) {
                                    field.visibility = false;
                                    group.visibility = false;
                                }
                                if (field.name == "ownership_type" && field.value == "") {

                                    field.value = 1;
                                    if (field.name === "unit_price") {
                                        field.disabled = false;
                                    }
                                }
                            } else if (vm.DeployItemId > 0) {

                                //debugger;

                                if (field.name == "ownership_type") {
                                    if (field.value == "") {
                                        field.value = 1;
                                        vm.ownershiptypevalue = field.value;
                                    } else {
                                        vm.ownershiptypevalue = field.value;
                                    }
                                }
                                if (parseInt(vm.ownershiptypevalue) === 1) {
                                    console.log("field ownership1", field.value)
                                    if (field.name === "unit_price") {
                                        field.disabled = false;
                                    }
                                    const hiddenFields = [
                                        "rent_start_date", "rent_end_date", "rent_rate", "rent_period", "rent_file",
                                        "lease_start_date", "lease_end_date", "lease_cost", "lease_period", "lease_file", "lease_type"
                                    ];

                                    if (hiddenFields.includes(field.name)) {
                                        field.visibility = false;
                                        group.visibility = false;
                                    }
                                } else if (parseInt(vm.ownershiptypevalue) === 2) {
                                    if (field.name == 'lease_cost') {
                                        //debugger
                                        field.disabled = true;

                                    }

                                    if (field.name == 'rent_start_date') {
                                        //debugger
                                        field.visibility = false;

                                    }
                                    if (field.name == 'rent_end_date') {
                                        field.visibility = false;

                                    }
                                    if (field.name == 'rent_rate') {
                                        field.visibility = false;

                                    }
                                    if (field.name == 'rent_period') {
                                        field.visibility = false;

                                    }
                                    if (field.name == 'rent_file') {
                                        field.visibility = false;

                                    }
                                } else if (parseInt(vm.ownershiptypevalue) === 3) {
                                    if (field.name == 'rent_rate') {
                                        //debugger
                                        field.disabled = true;

                                    }
                                    if (field.name == 'lease_start_date') {
                                        //debugger
                                        field.visibility = false;

                                    }
                                    if (field.name == 'lease_end_date') {
                                        field.visibility = false;

                                    }
                                    if (field.name == 'lease_cost') {
                                        field.visibility = false;

                                    }
                                    if (field.name == 'lease_period') {
                                        field.visibility = false;

                                    }
                                    if (field.name == 'lease_file') {
                                        field.visibility = false;

                                    }
                                    if (field.name == 'lease_type') {
                                        field.visibility = false;

                                    }
                                }
                            }

                            if (field.name == "deploy_item_id") {
                                field.visibility = false;
                                field.value = vm.DeployItemId;
                            }
                            if (field.name == "quantity") {
                                if (vm.DeployItemId > 0) {
                                    field.disabled = true;
                                } else {
                                    field.disabled = false;
                                    field.is_required = true;
                                    field.validationRules = {
                                        'required': true,
                                        integer: true,
                                        max_value: 9999,
                                        min_value: 1
                                    }

                                }

                            }

                            if (field.name == "asset_cost") {
                                if (vm.DeployItemId == 0 || vm.DeployItemId == null) {
                                    field.value = 0.00;
                                }

                                field.disabled = true;
                            }
                            if (field.name == "unit_price") {
                                //debugger;
                                field.validationRules = {
                                    'required': true,
                                    max: 8,
                                    min_value: 1
                                }
                                if (vm.DeployItemId == 0 || vm.DeployItemId == null) {
                                    field.value = 0.00;
                                } else {
                                    if (response.data.AssetDeployCatalogueDetails && response.data.AssetDeployCatalogueDetails.length > 0) {
                                        var unitPrice = response.data.AssetDeployCatalogueDetails[0].unit_price;
                                        field.value = unitPrice;
                                    } else {
                                        field.value = 0.00;
                                    }
                                }
                                // field.disabled = true;
                            }
                            if (field.name == "salvage_cost") {
                                //debugger;
                                //field.validationRules = {
                                    //max: 7,
                                    //min_value: 0
                               // }
                                if (vm.DeployItemId == 0 || vm.DeployItemId == null) {
                                    field.value = 0.00;
                                }
                                else if(vm.DeployItemId >0)
                                {
                                if(field.value=="")
                                {
                                    field.value = 0.00; 
                                }
                                }

                            }
                            if (field.name == "lease_cost") {
                                field.validationRules = {
                                    max: 7,
                                    min_value: 1
                                }
                                if (vm.DeployItemId == 0 || vm.DeployItemId == null) {
                                    field.value = 0.00;
                                }

                            }
                            if (field.name == "asset_catalogue_id") {
                                // debugger;

                                field.value = parseInt(vm.$route.params.id);
                                field.visibility = false;
                            }
                            if (field.name == "status_id") {
                                //debugger;

                                field.value = 1001;
                                field.visibility = false;
                            }
                            if (field.name == "deployement_type") {
                                ////debugger;
                                if (vm.DeployItemId == 0 || vm.DeployItemId == null) {
                                    field.value = "1";
                                } else if (vm.DeployItemId > 0) {
                                    field.disabled = true;
                                }

                            }

                            if (field.name == "product_file") {
                                //debugger;
                                var productAttachments = [];
                                //field.visibility = true;
                                vm.productAttachments = response.data.Attachment
                                    .filter(element => element.attachment_title === 'product_file')
                                    .map(element => ({
                                        attachmentId: element.asset_attachment_id,
                                        attachmentName: element.attachment_name,
                                        attachmentPath: element.attachment_path,
                                        attachmentDesc: element.attachment_desc,
                                        attachmentTitle: element.attachment_title,
                                    }));
                                let fileTypeList = vm.AttachmentDisallowedFileType(vm.AllowedFileType);
                                //console.log("fileTypeList:",fileTypeList)
                                if (fileTypeList != null) {
                                    field.config = {
                                        maxSize: 5,
                                        reject: [],
                                        showSelectedFiles: vm.productAttachments,
                                        onDeleteSelectedFiles: function (selected) {
                                            vm.onDeleteSelectedFiles(selected)
                                        },
                                        accept: vm.acceptArray,
                                        //onClickSelectedFiles: vm.onClickSelectedFiles,
                                        //onRemoveFile: vm.onRemoveFile,
                                        showAddIcon: false,
                                        onAddButtonClick: '',
                                        multiple: true
                                    };
                                }
                            }

                            if (field.name == "warranty_file") {
                                var warrantyAttachments = [];
                                vm.warrantyAttachments = response.data.Attachment
                                    .filter(element => element.attachment_title === 'warranty_file')
                                    .map(element =>
                                        ({
                                            attachmentId: element.asset_attachment_id,
                                            attachmentName: element.attachment_name,
                                            attachmentPath: element.attachment_path,
                                            attachmentDesc: element.attachment_desc,
                                            attachmentTitle: element.attachment_title,
                                        }));
                                let fileTypeList = vm.AttachmentDisallowedFileType(vm.AllowedFileType);
                                //console.log("fileTypeList:",fileTypeList)
                                if (fileTypeList != null) {
                                    field.config = {
                                        maxSize: 5,
                                        reject: [],
                                        showSelectedFiles: vm.warrantyAttachments,
                                        onDeleteSelectedFiles: function (selected) {
                                            vm.onDeleteSelectedFiles(selected)
                                        },
                                        accept: vm.acceptArray,
                                        //     onRemoveFile: vm.onRemoveFile,
                                        showAddIcon: false,
                                        onAddButtonClick: '',
                                        multiple: true
                                    };

                                }
                            }
                            if (field.name == "Insurance_file") {
                                var InsuranceAttachments = [];
                                vm.InsuranceAttachments = response.data.Attachment
                                    .filter(element => element.attachment_title === 'Insurance_file')
                                    .map(element => ({
                                        attachmentId: element.asset_attachment_id,
                                        attachmentName: element.attachment_name,
                                        attachmentPath: element.attachment_path,
                                        attachmentDesc: element.attachment_desc,
                                        attachmentTitle: element.attachment_title,
                                    }));
                                let fileTypeList = vm.AttachmentDisallowedFileType(vm.AllowedFileType);

                                if (fileTypeList != null) {
                                    field.config = {
                                        maxSize: 5,
                                        reject: [],
                                        showSelectedFiles: vm.InsuranceAttachments,
                                        onDeleteSelectedFiles: function (selected) {
                                            vm.onDeleteSelectedFiles(selected)
                                        },
                                        accept: vm.acceptArray,
                                        showAddIcon: false,
                                        onAddButtonClick: '',
                                        multiple: true
                                    };
                                }
                            }
                            if (field.name == "vender_file") {
                                var venderAttachments = [];
                                vm.venderAttachments = response.data.Attachment
                                    .filter(element => element.attachment_title === 'vender_file')
                                    .map(element =>
                                        ({
                                            attachmentId: element.asset_attachment_id,
                                            attachmentName: element.attachment_name,
                                            attachmentPath: element.attachment_path,
                                            attachmentDesc: element.attachment_desc,
                                            attachmentTitle: element.attachment_title,
                                        }));
                                let fileTypeList = vm.AttachmentDisallowedFileType(vm.AllowedFileType);

                                if (fileTypeList != null) {
                                    field.config = {
                                        maxSize: 5,
                                        reject: [],
                                        showSelectedFiles: vm.venderAttachments,
                                        onDeleteSelectedFiles: function (selected) {
                                            vm.onDeleteSelectedFiles(selected)
                                        },
                                        accept: vm.acceptArray,
                                        //    onClickSelectedFiles: vm.onClickSelectedFiles,
                                        //     onRemoveFile: vm.onRemoveFile,
                                        showAddIcon: false,
                                        onAddButtonClick: '',
                                        multiple: true
                                    };
                                }
                            }

                            if (field.name == "lease_file") {
                                var leaseAttachments = [];
                                vm.leaseAttachments = response.data.Attachment
                                    .filter(element => element.attachment_title === 'lease_file')
                                    .map(element =>
                                        ({
                                            attachmentId: element.asset_attachment_id,
                                            attachmentName: element.attachment_name,
                                            attachmentPath: element.attachment_path,
                                            attachmentDesc: element.attachment_desc,
                                            attachmentTitle: element.attachment_title,
                                        }));
                                let fileTypeList = vm.AttachmentDisallowedFileType(vm.AllowedFileType);
                                if (fileTypeList != null) {
                                    field.config = {
                                        maxSize: 5,
                                        reject: [],
                                        showSelectedFiles: vm.leaseAttachments,
                                        onDeleteSelectedFiles: function (selected) {
                                            vm.onDeleteSelectedFiles(selected)
                                        },
                                        accept: vm.acceptArray,
                                        //    onClickSelectedFiles: vm.onClickSelectedFiles,
                                        //     onRemoveFile: vm.onRemoveFile,
                                        showAddIcon: false,
                                        onAddButtonClick: '',
                                        multiple: true
                                    };
                                }
                            }
                            if (field.name == "rent_file") {
                                //debugger
                                //field.visibility = false;
                                var rentAttachments = [];
                                vm.rentAttachments = response.data.Attachment
                                    .filter(element => element.attachment_title === 'rent_file')
                                    .map(element =>
                                        ({
                                            attachmentId: element.asset_attachment_id,
                                            attachmentName: element.attachment_name,
                                            attachmentPath: element.attachment_path,
                                            attachmentDesc: element.attachment_desc,
                                            attachmentTitle: element.attachment_title,
                                        }));

                                let fileTypeList = vm.AttachmentDisallowedFileType(vm.AllowedFileType);
                                if (fileTypeList != null) {
                                    field.config = {
                                        maxSize: 5,
                                        reject: [],
                                        showSelectedFiles: vm.rentAttachments,
                                        onDeleteSelectedFiles: function (selected) {
                                            vm.onDeleteSelectedFiles(selected)
                                        },
                                        accept: vm.acceptArray,
                                        showAddIcon: false,
                                        onAddButtonClick: '',
                                        multiple: true
                                    };
                                }
                            }
                            field.config.onChange = vm.onChangeEventForFields;
                        });
                    });

                    vm.isLoading = false;
                }
            });
        },
        // onClickSelectedFiles:function(){},
        //  onRemoveFile:function(){},

        onChangeEventForFields: function (x, y, z) {
            //debugger
            let vm = this;

            if (y.name === "ownership_type") {
                vm.$refs.AddDeployProduct.updateProperty("ownership_type", "value", y.value);
                vm.FormSchema.forEach((group) => {
                    group.Data.forEach((field) => {
                        // Make all fields initially visible
                        field.visibility = true;
                        group.visibility = true;

                        const hiddenFieldsGenral = [
                            "asset_catalogue_id", "status_id", "deploy_item_id"
                        ];
                        if (hiddenFieldsGenral.includes(field.name)) {
                            field.visibility = false;

                        }
                        if (y.value == 1) {
                            // OWNED - hide both rent & lease fields

                            const hiddenFields = [
                                "rent_start_date", "rent_end_date", "rent_rate", "rent_period", "rent_file",
                                "lease_start_date", "lease_end_date", "lease_cost", "lease_period", "lease_file", "lease_type"
                            ];

                            if (hiddenFields.includes(field.name)) {
                                field.visibility = false;
                                group.visibility = false;
                            }

                            // Enable unit price field
                            //vm.FormSchema[0].Data[4].disabled = false;

                            const disabledOrEnable = [
                                "unit_price"
                            ];
                            if (disabledOrEnable.includes(field.name)) {
                                field.disabled = false;

                            }

                        } else if (y.value == 2) {
                            // LEASED - show lease fields, hide rent
                            const leaseFields = ["lease_start_date", "lease_end_date", "lease_cost", "lease_period", "lease_file", "lease_type"];
                            const rentFields = ["rent_start_date", "rent_end_date", "rent_rate", "rent_period", "rent_file"];

                            if (leaseFields.includes(field.name)) {
                                field.visibility = true;
                                if (field.group && field.group.group_name === "LEASE DETAILS") {
                                    field.group.visibility = true;
                                }
                            }
                            if (rentFields.includes(field.name)) {
                                field.visibility = false;
                                if (field.group && field.group.group_name === "RENT DETAILS") {
                                    field.group.visibility = false;
                                }
                            }

                            //vm.FormSchema[0].Data[4].disabled = true;
                            const disabledOrEnable = [
                                "lease_cost"
                            ];
                            if (disabledOrEnable.includes(field.name)) {
                                field.disabled = true;

                            }
                            let assetCostField = this.$refs.AddDeployProduct.getPropertyValue("asset_cost", "value");

                            vm.$refs.AddDeployProduct.updateProperty("lease_cost", "value", assetCostField);

                        } else if (y.value == 3) {
                            // RENTED - show rent fields, hide lease
                            const rentFields = ["rent_start_date", "rent_end_date", "rent_rate", "rent_period", "rent_file"];
                            const leaseFields = ["lease_start_date", "lease_end_date", "lease_cost", "lease_period", "lease_file", "lease_type"];

                            if (rentFields.includes(field.name)) {
                                field.visibility = true;
                                if (field.group && field.group.group_name === "RENT DETAILS") {
                                    field.group.visibility = true;
                                }
                            }
                            if (leaseFields.includes(field.name)) {
                                field.visibility = false;
                                if (field.group && field.group.group_name === "LEASE DETAILS") {
                                    field.group.visibility = false;
                                }
                            }
                            let assetCostField = this.$refs.AddDeployProduct.getPropertyValue("asset_cost", "value");

                            vm.$refs.AddDeployProduct.updateProperty("rent_rate", "value", assetCostField);
                            //vm.FormSchema[0].Data[4].disabled = true;
                            const disabledOrEnable = [
                                "rent_rate"
                            ];
                            if (disabledOrEnable.includes(field.name)) {
                                field.disabled = true;

                            }

                        } else {
                            //vm.FormSchema[0].Data[4].disabled = true;
                            const disabledOrEnable = [
                                "unit_price"
                            ];
                            if (disabledOrEnable.includes(field.name)) {
                                field.disabled = true;

                            }
                            const hiddenFields = [
                                "rent_start_date", "rent_end_date", "rent_rate", "rent_period", "rent_file",
                                "lease_start_date", "lease_end_date", "lease_cost", "lease_period", "lease_file", "lease_type"
                            ];

                            if (hiddenFields.includes(field.name)) {
                                field.visibility = false;
                                group.visibility = false;
                            }
                        }
                    });
                });
            }
            if (y.name == "product_file" || y.name == "vender_file" || y.name == "Insurance_file" || y.name == "warranty_file" || y.name == "lease_file" || y.name == "rent_file") {
                // debugger;
                // Remove the previously uploaded file with the same AttachmentTitle
                const index = vm.fileMulitpleData.findIndex(f => f.AttachmentTitle === y.name);
                if (index !== -1) {
                    vm.fileMulitpleData.splice(index, 1);
                }
                vm.GetBase64String(y.value, y.name);
            }
            if (y.name == "asset_catalogue_id") {
                // debugger;
                field.value = parseInt(vm.$route.params.id);
            }
            if (y.name === "quantity") {
                // debugger;
                if (y.value.length > 4) {
                    let quantity = parseFloat(y.value.slice(0, 4) || 0);
                    vm.$refs.AddDeployProduct.updateProperty("quantity", "value", quantity);
                }

                // Do something with quantity

                //console.log("Quantity value is", quantity);
            }

            const quantity = vm.$refs.AddDeployProduct.getPropertyValue("quantity", "value");

            const unitprice = this.$refs.AddDeployProduct.getPropertyValue("unit_price", "value");

            let assetCostField = this.$refs.AddDeployProduct.getPropertyValue("asset_cost", "value");

            //var unitPrice = parseFloat(unitprice == "" ? 0 : unitprice);

            if (y.name == "quantity") {
                //debugger;
                if (parseFloat(y.value) > 0 && unitprice > 0) {
                    var assetCost = parseFloat(y.value) * parseFloat(unitprice);
                    //this.FormSchema[0].Data.find(f => f.name === fieldName)

                    vm.$refs.AddDeployProduct.updateProperty("asset_cost", "value", assetCost);

                    let ownershiptypevalue = this.$refs.AddDeployProduct.getPropertyValue("ownership_type", "value");
                    if (ownershiptypevalue == 2) {
                        vm.$refs.AddDeployProduct.updateProperty("lease_cost", "value", assetCost);

                    } else if (ownershiptypevalue == 3) {
                        vm.$refs.AddDeployProduct.updateProperty("rent_rate", "value", assetCost);

                    }

                } else {
                    vm.$refs.AddDeployProduct.updateProperty("unit_price", "value", 1);
                    var assetCost = parseFloat(y.value) * parseFloat(1);
                    //vm.FormSchema[0].Data[5].value = "0.000";
                    vm.$refs.AddDeployProduct.updateProperty("asset_cost", "value", assetCost);

                    let ownershiptypevalue = this.$refs.AddDeployProduct.getPropertyValue("ownership_type", "value");
                    if (ownershiptypevalue == 2) {
                        vm.$refs.AddDeployProduct.updateProperty("lease_cost", "value", assetCost);

                    } else if (ownershiptypevalue == 3) {
                        vm.$refs.AddDeployProduct.updateProperty("rent_rate", "value", assetCost);

                    }
                }
            }
            if (y.name == "unit_price") {
                // debugger;

                let unitPrice = y.value;

                // Limit unit price to 8 digits before parsing
                if (unitPrice.length > 8) {
                    unitPrice = unitPrice.slice(0, 8);
                    vm.$refs.AddDeployProduct.updateProperty("unit_price", "value", unitPrice);
                }

                let assetCostField = 0;
                if (parseFloat(unitPrice) > 0 && quantity > 0) {

                    var assetCost = parseFloat(unitPrice) * parseFloat(quantity);
                    assetCostField = assetCost.toFixed(2);
                } else {
                    vm.$refs.AddDeployProduct.updateProperty("quantity", "value", 1);
                    assetCostField = parseFloat(unitPrice);
                }
                vm.$refs.AddDeployProduct.updateProperty("unit_price", "value", unitPrice);

                vm.$refs.AddDeployProduct.updateProperty("asset_cost", "value", assetCostField);
                //this.updateProperty("unit_price", "value", assetCostField);

                let ownershiptypevalue = this.$refs.AddDeployProduct.getPropertyValue("ownership_type", "value");
                if (ownershiptypevalue == 2) {
                    vm.$refs.AddDeployProduct.updateProperty("lease_cost", "value", assetCost);

                } else if (ownershiptypevalue == 3) {
                    vm.$refs.AddDeployProduct.updateProperty("rent_rate", "value", assetCost);

                }
            }

            if (y.name == "salvage_cost") {
                //debugger;
                if (parseFloat(y.value) > unitprice) {
                    vm.ShowAlert(vm.$t("Salvage Cost must be less than Unit Price."), "warning", vm.$t("Alert"));
                    y.value = 0.00;
                }
            }

        },
        GetBase64String: function (evt, type) {
            //debugger;
            try {
                //debugger;
                var vm = this;
                var f = evt[0]; // FileList object
                // var f = evt.target.files[0]; // FileList object
                var reader = new FileReader();
                let fileObj = {};
                // Closure to capture the file information.
                reader.onload = (function (theFile) {
                    return function (e) {
                        var binaryData = e.target.result;
                        //Converting Binary Data to base 64
                        var base64StringEncoded = window.btoa(binaryData);
                        //showing file converted to base64
                        var fileName = f.name;
                        vm.fileName = fileName;
                        var n = fileName.lastIndexOf(".");
                        var extensionName = fileName.substring(n + 1, fileName.length);
                        vm.fileExt += "." + extensionName;
                        var attachemnetMime = '{"ContentType":"' + f.type + '","Size":"' + f.size + '","Extension":"' + extensionName + '"}';
                        var fileSize = f.size;
                        vm.fileSize = fileSize;

                        fileObj.attachement_mime = attachemnetMime,
                            fileObj.fileName = fileName,
                            fileObj.base64String = base64StringEncoded,
                            fileObj.fileSize = f.size,
                            fileObj.contentType = f.type,
                            fileObj.ModuleName = 'Asset',
                            fileObj.SubModuleCode = 'DEPLOY_PRODUCT',
                            fileObj.AttachmentTitle = type

                        vm.fileMulitpleData.push(fileObj);
                    };
                })(f);
                // Read in the image file as a data URL.
                reader.readAsBinaryString(f);

            } catch (ex) {}
        },
        onDeleteSelectedFiles: function (selected) {
            //debugger;
            var vm = this;
            //const fieldNames = ['product_file', 'warranty_file', 'Insurance_file', 'vender_file', 'lease_file'];

            if (selected.attachmentId > 0) {
                var params = `attachmentId=${selected.attachmentId}&statusId=1003`;
                vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("File")), function () {

                    DataService.DeleteFile(params).then(response => {
                        if (response.data == true) {
                            vm.ShowAlert(vm.$t("FileDeleted"), "success", vm.$t('Alert'));
                            vm.$parent.FetchData();
                        } else {
                            vm.ShowAlert(vm.$t("Unknown  Error"), "failure", vm.$t('Alert'));
                        }
                    })
                })
            }

            if (selected.attachmentTitle == 'product_file') {
                const field = this.FormSchema[1].Data.find(f => f.name === selected.attachmentTitle);
                console.log("field:", field)
                if (field && field.config) {
                    this.$delete(field.config, 'showSelectedFiles');
                }

            } else if (selected.attachmentTitle == 'warranty_file') {
                const field = this.FormSchema[2].Data.find(f => f.name === selected.attachmentTitle);
                console.log("field:", field)
                if (field && field.config) {
                    this.$delete(field.config, 'showSelectedFiles');
                }

            } else if (selected.attachmentTitle == 'Insurance_file') {

                const field = this.FormSchema[3].Data.find(f => f.name === selected.attachmentTitle);
                console.log("field:", field)
                if (field && field.config) {
                    this.$delete(field.config, 'showSelectedFiles');
                }

            } else if (selected.attachmentTitle == 'vender_file') {

                const field = this.FormSchema[4].Data.find(f => f.name === selected.attachmentTitle);
                console.log("field:", field)
                if (field && field.config) {
                    this.$delete(field.config, 'showSelectedFiles');
                }

            } else if (selected.attachmentTitle == 'lease_file') {

                const field = this.FormSchema[5].Data.find(f => f.name === selected.attachmentTitle);
                console.log("field:", field)
                if (field && field.config) {
                    this.$delete(field.config, 'showSelectedFiles');
                }

            } else if (selected.attachmentTitle == 'rent_file') {

                const field = this.FormSchema[6].Data.find(f => f.name === selected.attachmentTitle);
                console.log("field:", field)
                if (field && field.config) {
                    this.$delete(field.config, 'showSelectedFiles');
                }

            }

        },
        onSubmit: function (e) {
             debugger;
            var vm = this;
            vm.$refs.AddDeploy.validate().then(result => {
                if (result) {
                    vm.isLoading = true;
                    var CustomFieldArray = vm.$refs.AddDeployProduct.ConvertDynamicFormObjToCustomFieldObj(vm.FormSchema);

                    // CustomFieldArray.forEach((item, index) => {
                    //if (item.field_name == 'location') {
                    // item.field_value = vm.TreeValue == null ? 0 : vm.TreeValue;
                    //}
                    //})
                    debugger;
                    var obj = {
                        data: CustomFieldArray,
                        moduleCode: "Asset",
                        subModuleCode: "DEPLOY_PRODUCT",
                        attachmentData: vm.fileMulitpleData.length > 0 ? vm.fileMulitpleData : null
                    }
                    // debugger;
                    // DataService.IsDuplicateAssetCatalog(JSON.stringify(obj)).then(function (response) {
                    //debugger;

                    DataService.SaveDynamicForm(JSON.stringify(obj)).then(function (response) {
                        //debugger;
                        if (response != null && response.data != null && response.data[0].Status == "Success") {
                            if (vm.DeployItemId > 0) {
                                vm.ShowAlert(vm.$t("Product Deploy  has been updated Successfully"), "success", vm.$t('Alert'));
                            } else {
                                vm.ShowAlert(vm.$t("Product Deploy  has been Saved Successfully"), "success", vm.$t('Alert'));
                            }
                            vm.isLoading = false;
                            vm.$parent.DeployClosePOp();
                            vm.$parent.FetchData();

                        } else {
                            vm.ShowAlert(vm.$t("ErrorWhileSaving", [vm.$t("Product")]), "danger", true, vm.$t("Alert"));

                            vm.isLoading = false;

                        }
                    })
                } else {
                    //vm.ShowAlert((vm.$t("AlreadyExistRec")), "danger", true, vm.$t("Alert"));
                    vm.isLoading = false;
                }
            });
            //}

        },
    },

};
