        setFile(event, index, type) {
                const file = event.target.files[0];
                if (!file) return;

                const typeMap = {
                    A: this.AttachmentDivData,
                    B: this.AttachmentDivData1,
                    C: this.AttachmentDivData2,
                    D: this.AttachmentDivData3,
                    E: this.AttachmentDivData4,
                    F: this.AttachmentDivData5
                };

                const targetArray = typeMap[type];
                if (targetArray && targetArray[index]) {
                    targetArray[index].fileName = file.name;
                    targetArray[index].fileUploaded = file;
                } else {
                    console.warn(`Invalid type '${type}' or index '${index}' out of bounds.`);
                }
        },     
        Clear(count, indx, type) {
            const vm = this;
            const attachmentMap = {
                A: vm.AttachmentDivData,
                B: vm.AttachmentDivData1,
                C: vm.AttachmentDivData2,
                D: vm.AttachmentDivData3,
                E: vm.AttachmentDivData4,
                F: vm.AttachmentDivData5
            };

            const group = attachmentMap[type];
            if (group) {
                group.forEach(element => {
                    if (element.count === count) {
                        element.fileName = '';
                        element.fileUploaded = null; // Also clear uploaded file if necessary
                    }
                });
            }
            if (count === undefined && indx === undefined && type === undefined) {
                Object.keys(attachmentMap).forEach(key => {
                    const group = attachmentMap[key];
                    group.forEach((item, index) => {
                        vm.$set(group, index, {
                            ...item,
                            fileName: '',
                            fileUploaded: null,                          
                        });
                    });
                });
            }
        },
        removeRow(event) {
            var vm = this;
            const index = vm.AttachmentDivData.findIndex(x => x.count === event);
            if (index !== -1) {
                vm.AttachmentDivData.splice(index, 1);
            }
            return true
        },

