        checkSalvageCost(field, data) {
            var vm = this;
            let unitPrice = parseInt(vm.FormSchema[0].Data[4].value);
            let salvageCost = parseInt(data.value.replace(/[^0-9]/g, ""));

            if(parseInt(vm.FormSchema[0].Data[1].value) <= 1){
                if (salvageCost >= unitPrice) {
                    vm.ShowAlert(vm.$t("Salvage Cost must be less than Unit Price."), "warning", vm.$t("Alert"));
                    return vm.FormSchema[4].Data[2].value = "";
                }
                if(salvageCost.toString()=='NaN'){
                    return vm.FormSchema[4].Data[2].value = "";
                }else{
                    return vm.FormSchema[4].Data[2].value = salvageCost.toString();
                } 
            }
            else{
                return vm.FormSchema[4].Data[2].value = "";
            } 
        },

