        onListDeploy: function (formfields, val) {
            var vm = this;
            vm.noRecord = false;

              const currentAttachments = [
                vm.AttachmentDivData,
                vm.AttachmentDivData1,
                vm.AttachmentDivData2,
                vm.AttachmentDivData3,
                vm.AttachmentDivData4,
                vm.AttachmentDivData5
            ];

            // Deep copy the FormSchema
            const copiedFormData = JSON.parse(JSON.stringify(vm.FormSchema));

            // Collect current attachment data (file references and titles)
            const attachmentsForThisItem = currentAttachments.map(group => {
                return group.map(item => ({
                    AttachmentTitle: item.AttachmentTitle,
                    fileName: item.fileName,
                    fileUploaded: item.fileUploaded
                }));
            });

            // Add to master array
            vm.newarryaofData.push({                
                Attachments: attachmentsForThisItem
            });

            let LocationObj = vm.LocationData.find(item => item.COMPANY_LOCATION_ID == formfields.Location);

            if (!LocationObj) {
                return vm.ShowAlert("Invalid location selected.", "warning", vm.$t("Alert"));
            }

            let DataObject = {
                LocationName: LocationObj.LOCATION_NAME,
                DeployMentType: formfields.DeployMentType,
                DepreciationRule: formfields.DepreciationRule,
                InsuranceReferenceNumber: formfields.InsuranceReferenceNumber,
                InsuranceValidUpto: formfields.InsuranceValidUpto,
                InvoiceDate: formfields.InvoiceDate,
                InvoiceNumber: formfields.InvoiceNumber,
                Location: formfields.Location,
                Manufacture: formfields.Manufacture,
                Model: formfields.Model,
                NameofInsurer: formfields.NameofInsurer,
                OrderDaTe: formfields.OrderDaTe,
                ProductCostQty: formfields.ProductCostQty,
                ProductLifeInYears: formfields.ProductLifeInYears,
                Quantity: formfields.Quantity,
                RefPurchaseOrder: formfields.RefPurchaseOrder,
                SalvageCost: formfields.SalvageCost,
                UnitPrice: formfields.UnitPrice || 0,
                Vendor: formfields.Vendor,
                WarrantyDuration: formfields.WarrantyDuration,
                ItemLife: formfields.ProductLifeInYears,
                OwnershipType: formfields.OwnershipType || '',
                RentStartDate: formfields.RentStartDate || '',
                RentEndDate: formfields.RentEndDate || '',
                RentRate: formfields.RentRate || 0,
                RentPeriod: formfields.RentPeriod || '',
                LeaseStartDate: formfields.LeaseStartDate || '',
                LeaseEndDate: formfields.LeaseEndDate || '',
                LeasePriod: formfields.LeasePriod,
                LeaseCost: formfields.LeaseCost || 0,
                LeaseType: formfields.LeaseType || '',
                LeaseAgreementNumber: formfields.LeaseAgreementNumber || '',
                PurchaseDate: formfields.PurchaseDate || '',
                InstallationDate: formfields.InstallationDate || ''
            };
            if (DataObject.SalvageCost >= DataObject.UnitPrice && DataObject.OwnershipType <= 1) {
                return vm.ShowAlert(vm.$t("Salvage Cost must be less than Unit Price."), "warning", vm.$t("Alert"));
            }

            vm.arryaofData.push(DataObject);
            vm.LocationName = LocationObj.LOCATION_NAME;

            // Reset form fields
            vm.FormSchema.forEach((group) => {
                group.Data.forEach(field => {
                    field.value = (typeof field.value === 'number') ? 0 : '';
                    if (field.validationRules && field.validationRules.required) {
                        field.validationRules.required = false;
                    }
                });
            });

            // Reset specific values manually if needed            
            vm.Clear();
            vm.FormSchema[0].Data[0].value = null
            vm.FormSchema[0].Data[1].value = 1
            let obj = {
                value: 1
            }
            vm.changeOwnerShipType('', obj);
            vm.FormSchema[0].Data[2].value = 1

