                    RentEndDate: vm.FormSchema[6].Data[1].value,
                    RentPeriod: vm.FormSchema[6].Data[2].value,
                    RentRate: vm.FormSchema[6].Data[3].value || 0
                };

                if (myObj.SalvageCost >= myObj.UnitPrice && myObj.OwnershipType <= 1) {
                    return vm.ShowAlert(vm.$t("Salvage Cost must be less than Unit Price."), "warning", vm.$t("Alert"));
                }

                ArrayData.push(myObj);

                 const attachmentGroups = [
                    vm.AttachmentDivData,
                    vm.AttachmentDivData1,
                    vm.AttachmentDivData2,
                    vm.AttachmentDivData3,
                    vm.AttachmentDivData4,
                    vm.AttachmentDivData5
                ];
                
                const entryIndex=0;

                attachmentGroups.forEach((group, groupIndex) => {
                    const titleString = group.map(item => item.AttachmentTitle).join(",");
                    ArrayData[0][`AttachmentTitle${groupIndex}`] = titleString;

                    group.forEach((item, fileIndex) => {
                        if (item.fileUploaded) {
                            const fileName = item.fileName;
                            const fileType = fileName.split('.').pop().toLowerCase();

                            formData.append(`File_${entryIndex}_${groupIndex}_${fileIndex}`, item.fileUploaded, fileName);

                            if (!allowedFileTypes.has(fileType)) {
                                vm.TypeFileArr.push(fileName);
                            }
                        }
                    });

                     formData.append(`AttachmentTitle${entryIndex}_${groupIndex}`, titleString);
                });
            }

            // File Upload Handling           

            formData.append("jsonData", JSON.stringify(ArrayData));

            await DataService.SaveDeploy(formData).then(response => {
                const msg = response.data.msg;

                if (msg === 'DeployedSuccessfully') {
                    vm.ClosePopup();
                    vm.$parent.FetchData();
                    vm.ShowAlert(vm.$t('ProductDeployAdd'), "success", true, vm.$t("Alert"));
                } else if (msg === 'ValidFileUploadMsg') {
                    vm.ShowAlert(vm.$t("InvalidFileUploadMsg", [vm.TypeFileArr[0]]) + vm.FileTypeAllowedToolTip, "failure", true, vm.$t("Alert"));
                } else if (msg === 'DeployItem') {
                    vm.ClosePopup();
                    vm.$parent.FetchData();
                    vm.ShowAlert(vm.$t('ProductDeployUpdated'), "success", true, vm.$t("Alert"));
                } else {
                    if(msg==='ExceedAllowedSize')
                    {
                        vm.ShowAlert(vm.$t('FileSizeExceedMsg'), "failure", true, vm.$t("Alert"))
                        //vm.ShowAlert((vm.$t('size_exceed', [vm.$t('Asset')]), "warning", true, vm.$t("Alert")))
                    }
                    else{
                        vm.ShowAlert(vm.$t("UnknownError"), "failure", vm.$t('Alert'));
                    }
                    
                }
            });
        },


        async BindDataFileds() {
            var vm = this;
            vm.isLoading = true;
            var url = `DeployItemId=${vm.DeployItemId}&AssetCatalogId=${this.$route.params.id}`;
            await DataService.GetDeployItems(url).then(response => {
                vm.isLoading = false;
                if (JSON.parse(response.data.result) != null) {

                    var fieldDataValues = JSON.parse(response.data.result);
                    if (JSON.parse(response.data.result).length > 0) {
                        vm.FormSchema[0].Data[0].value = fieldDataValues[0].location;
                        vm.FormSchema[0].Data[0].disabled = true;
                        vm.FormSchema[0].Data[1].disabled = false;
                        vm.FormSchema[0].Data[2].disabled = true;

                        vm.FormSchema[0].Data[3].disabled = true;

                        if (fieldDataValues[0]?.ownership_type) {
                            vm.FormSchema[0].Data[1].value = fieldDataValues[0].ownership_type
                            let obj = {
                                value: fieldDataValues[0].ownership_type
                            }
                            vm.changeOwnerShipType('', obj);

                            if (fieldDataValues[0]?.ownership_type == '2') {
                                vm.FormSchema[0].Data[4].validationRules.required = false;
                                vm.FormSchema[0].Data[4].disabled = true,
                                vm.FormSchema[5].Data[0].value = fieldDataValues[0].lease_start_date
                                vm.FormSchema[5].Data[1].value = fieldDataValues[0].lease_end_date
                                vm.FormSchema[5].Data[2].value = fieldDataValues[0].lease_period
                                vm.FormSchema[5].Data[3].value = fieldDataValues[0].lease_cost
                                vm.FormSchema[5].Data[4].value = fieldDataValues[0].lease_type
                                vm.FormSchema[5].Data[5].value = fieldDataValues[0].lease_agreement_number

                            }
                            if (fieldDataValues[0]?.ownership_type == '3') {
                                vm.FormSchema[0].Data[4].validationRules.required = false;
                                vm.FormSchema[0].Data[4].disabled = true,
                                vm.FormSchema[6].Data[0].value = fieldDataValues[0].rent_start_date
                                vm.FormSchema[6].Data[1].value = fieldDataValues[0].rent_end_date
                                vm.FormSchema[6].Data[2].value = fieldDataValues[0].rent_period
                                vm.FormSchema[6].Data[3].value = fieldDataValues[0].rent_rate

                            }
                        }
                        vm.FormSchema[0].Data[2].value = fieldDataValues[0].deployement_type == "1" ? '1' : '2';
                        vm.FormSchema[0].Data[3].value = fieldDataValues[0].quantity;
                        vm.FormSchema[0].Data[4].value = fieldDataValues[0].unit_price;
                        vm.FormSchema[0].Data[5].value = fieldDataValues[0].asset_cost.toFixed(2),

                            vm.FormSchema[1].Data[0].value = fieldDataValues[0].model;
                        vm.FormSchema[1].Data[1].value = fieldDataValues[0].manufacturer;
                        vm.FormSchema[1].Data[2].value = fieldDataValues[0].item_life;

                        vm.FormSchema[2].Data[0].value = fieldDataValues[0].vendor;

                        vm.FormSchema[2].Data[1].value = fieldDataValues[0].purchase_order;
                        vm.FormSchema[2].Data[2].value = fieldDataValues[0].order_date;
                        vm.FormSchema[2].Data[3].value = fieldDataValues[0].invoice_number;
                        vm.FormSchema[2].Data[4].value = fieldDataValues[0].invoice_date;
                        vm.FormSchema[2].Data[5].value = fieldDataValues[0].purchase_date;
                        vm.FormSchema[2].Data[6].value = fieldDataValues[0].installation_date;



                        vm.FormSchema[3].Data[0].value = fieldDataValues[0].insurance_ref_number;
                        vm.FormSchema[3].Data[1].value = fieldDataValues[0].insurer_name;
                        vm.FormSchema[3].Data[2].value = fieldDataValues[0].insurance_valid_upto;

                        vm.FormSchema[4].Data[0].value = fieldDataValues[0].warranty_duration;
                        if (fieldDataValues[0]?.depreciation_rule == '0') {
                            //
                        } else {
                            vm.FormSchema[4].Data[1].value = fieldDataValues[0].depreciation_rule;
                        }

                        vm.FormSchema[4].Data[2].value = fieldDataValues[0].salvage_cost;
                    }
                }
                setTimeout(function () {
                    vm.ResponsiveDataTable('tablelistingdata')
                }, 500);
            });

        },

        async GetDepreciationRule() {
            var vm = this;
            vm.isLoading = true;
            vm.DepreciationData = [];
            var obj = {};
            await DataService.GetDepreciationRuleList().then(response => {
                if (typeof response.data === 'string') {
                    vm.DepreciationData = JSON.parse(response.data);
                } else {
                    vm.DepreciationData = response.data;
                }
                //vm.DepreciationData = JSON.parse(response.data);
                vm.DepreciationData.forEach((item, index) => {
                    obj = {
                        name: item.DEPRECIATION_RULE_NAME,
                        value: item.DEPRECIATION_RULE_ID
                    }
                    vm.dData.push(obj);
                });
                (vm.FormSchema)[4].Data[1].config.options = vm.dData;
                vm.$refs.AddDeployProduct.UpdateKeyValue();

            });
            vm.isLoading = false;
        },

        FetchData() {
            var vm = this;
            var url = `DeployItemId=${parseInt(vm.ClickType == "UPDATE" ? vm.DeployItemId : '')}&isDelete=1&flag=`;
            DataService.ViewDeployeFiles(url).then(response => {
                // if (JSON.parse(response.data ).data  != null) {
                const allData = JSON.parse(response.data).data;
               // const filteredData = allData.filter(item => item.DeployItemId !=null);
                if (allData.length > 0) {
                    vm.AttachmentList = allData;
                    vm.TotalRecords = vm.AttachmentList.length;
                    vm.TotalPages = Math.ceil(vm.TotalRecords / vm.PageSize);
                    vm.CurrentPage = vm.PageNumber;
                    vm.noRecord = false;
                } else {
                    vm.noRecord = true;
                    vm.AttachmentList = [];
                    vm.TotalRecords = 0;
                }
                // }
                setTimeout(function () {
                    vm.ResponsiveDataTable('tablelistingdata')
                }, 500);
            });
        },
        openActionIcon(e) {
            e.target.nextSibling.removeAttribute('style');
            e.target.nextSibling.setAttribute('style', 'width:240px;');
            e.target.nextSibling.style.display = 'block';
        },     
        DeleteAttachment: function (e) {
            var vm = this;
            var params = `attachmentId=${e.ASSET_ATTACHMENT_ID}&statusId=1003`;
            vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("File")), function () {
                DataService.DeleteFile(params).then(response => {
                    if (response.data == true) {
                        vm.ShowAlert(vm.$t("FileDeleted"), "success", vm.$t('Alert'));
                        vm.FetchData();
                    }
                    else {
                        vm.ShowAlert(vm.$t("Unknown  Error"), "failure", vm.$t('Alert'));
                    }
                })
            })        
        },
        DownLoadFile(item) {
            var vm = this;
            vm.isLoading=true;
            var param = `filePath=${item.ATTACHMENT_PATH}`;
            DataService.DownloadAttachment(param).then(function (response) {
                const byteData = response.data;
                const fileURL = `data:${item.ATTACHMENT_TYPE};base64,${byteData}`;
                var fileLink = document.createElement('a');
                fileLink.href = fileURL;
                fileLink.setAttribute('download', item.ATTACHMENT_NAME);
                document.body.appendChild(fileLink);
                fileLink.click();
            });
            vm.isLoading=false;
        },
        GetBlobUrl: async function () {
            var vm = this;
           await DataService.GetBlobUrl().then((response) => {
                vm.BlobUrl = response.data[0].CONFIG_DATA_VALUE;            
            })
        },
        
    },
};
</script>

