                                dateStr = dateStr.split(' ')[0];
                            }
                            
                            if (dateStr && typeof dateStr === 'string') {
                                // Parse the date string and add one day to compensate for timezone offset
                                // This fixes the issue where the date appears one day less when reopened
                                const dateParts = dateStr.split('-');
                                if (dateParts.length === 3) {
                                    // Create date and add one day to compensate for timezone conversion
                                    const date = new Date(dateStr);
                                    date.setDate(date.getDate() + 1);
                                    vm.InfoData[field] = date;
                                }
                            }
