        async checkParentAssetDuplicates() {
            if (!this.InfoData || this.InfoData.length === 0) return false;
            const parentAssets =this.InfoData.parent_asset
            if (!parentAssets){
                this.InfoData.parent_asset_id='';
                return false;
            } 

            try {
                const payload = { ItemNames: [parentAssets] };
                const response = await DataService.CheckBulkProductName(payload);
                if (response?.data?.conflicts?.length > 0) {
                    this.InfoData.parent_asset_id=response?.data?.conflicts[0].asset_catalogue_id;
                    return false;

                } else {
                    this.InfoData.parent_asset_id='';
                    return true;
                }

            } catch (error) {
                console.error('Bulk parent asset check failed:', error);
                return true; // fail-safe: block submission
            }
        },
         async validateMacAddressUnique(value) {
            this.MacAddressError = '';
            if (!value) return true; // allow save if empty (optional)
            try {
                const param = `MacAddress=${encodeURIComponent(value)}&relatedInfoId=${this.RelatedInfoId}`;
                const res = await DataService.CheckMacAddressUnique(param);

                if (res?.data && res.data.isUnique === false) {
                    this.MacAddressError = 'Mac Address already exists';
                    return false;
                }
                return true;
            } catch (err) {
                console.error('Error checking serial number:', err);
                this.MacAddressError = 'Validation failed';
                return false;
            }
        },
        async SaveRelatedInfo() {
            const vm = this;
            vm.isLoading = true;
            const parentAssetDuplicates = await this.checkParentAssetDuplicates();

            if (parentAssetDuplicates) { 
                // vm.ShowAlert(vm.$t('ParentAssetNotFound'),
                //     'failure',
                //     vm.$t('Alert')
                // );
                vm.ParentAssetError=vm.$t('ParentAssetNotFound');
                vm.isLoading = false;
                return;
            }
            let checkValidUniquname = await vm.validateUniqueName();
            if (checkValidUniquname === false) {
                vm.isLoading = false;
                return; // 🔴 BLOCK SAVE
            }
            // 1. Validate the form
            const isFormValid = await vm.$refs.RejectForm.validate();
            if (!isFormValid) {
                vm.isLoading = false;
                return;
            }

            // 2. Validate Serial Number and Mac Address Uniqueness
            const serialValue = vm.InfoData.SerialNumber || ''; // ensure value is present
            const isSerialUnique = await vm.checkSerialNumberUnique(serialValue);
            if (!isSerialUnique) {
                vm.isLoading = false;
                vm.ShowAlert(vm.$t("CorrectHighlightedErrors"), "warning", vm.$t("Alert"));
                return; // 🔴 BLOCK SAVE
            }  

            const MacAddressValue = vm.InfoData.mac_address || ''; // ensure value is present
            const isMacAddressUnique = await vm.validateMacAddressUnique(MacAddressValue);
            if (!isMacAddressUnique) {
                vm.isLoading = false;
                vm.ShowAlert(vm.$t("CorrectHighlightedErrors"), "warning", vm.$t("Alert"));
                return; 
            }
            // 3. Proceed to Save
            const formData = new FormData();
            formData.append("postString", JSON.stringify(vm.InfoData));
            formData.append("Files", vm.selectedFile.length === 0 ? 0 : vm.selectedFile);

            try {
                const response = await DataService.SaveRelatedInfo(formData);

                if (response?.data) {
                    const code = response.data.error;

                    switch (code) {
                        case '100':
                            vm.ShowAlert(vm.$t("RelatedInformationUpdate"), "success", vm.$t('Alert'));
                            vm.$parent.FetchData();
                            vm.ClosePOPuP();
                            break;
                        case '110':
                            vm.ShowAlert(vm.$t("AllowedFiles") + vm.FileTypeAllowed, "failure", true, vm.$t('Alert'));
                            break;
                        case '121':
                            vm.ShowAlert(vm.$t("Storage Size Exceeded than Limit"), "failure", true, vm.$t('Alert'));
                            vm.ClosePOPuP();
                            break;
                        case '99':
                            vm.ShowAlert(vm.$t("File Uploading Failed"), "failure", true, vm.$t('Alert'));
                            vm.ClosePOPuP();
                            break;
                        default:
                            vm.ShowAlert(vm.$t("Unknown Error Occur"), "failure", true, vm.$t('Alert'));
                            vm.ClosePOPuP();
                            break;
                    }
                }
            } catch (e) {
                console.error('Error while saving:', e);
            }

            vm.isLoading = false;
        },

        handleFileUpload(event) {
            const file = event.target.files[0];
            if (file) {
                // Store the selected file in the Vue data property
                this.selectedFile = file;

                //console.log("Selected File:", this.selectedFile);
                // You can perform any additional logic or operations with the file here
            }
        },

        formatDate(dateString) {

            if (dateString) {
                const date = new Date(dateString);
                if (!isNaN(date.getTime())) {
                    // Customize the date format using the appropriate format string
                    const formatted = date.toLocaleDateString('en-US', {
                        month: 'numeric',
                        day: 'numeric',
                        year: 'numeric',
                        hour: 'numeric',
                        minute: 'numeric',
                        hour12: true,
                    });
                    return formatted;
                }
            }
            return '';
        },
        formatDateString(value) {

            return value;
        },

        Cancel: function (item) {
            this.$emit('ClosePOPuP', item);
            vm.$parent.FetchData();

        },
        ClosePOPuP: function (item) {

            this.$emit('ClosePOPuP', item);
        },
        async checkSerialNumberUnique(value) {
            //debugger;
            this.serialNumberError = '';

            if (!value) return true; // allow save if empty (optional)

            try {
                const param = `serialNumber=${encodeURIComponent(value)}&relatedInfoId=${this.RelatedInfoId}`;

                const res = await DataService.CheckSerialNumberUnique(param);

                if (res?.data && res.data.isUnique === false) {
                    this.serialNumberError = 'Serial number already exists';
                    return false;
                }
                return true;
            } catch (err) {
                console.error('Error checking serial number:', err);
                this.serialNumberError = 'Validation failed';
                return false;
            }
        },

        // UniqueName validation method
        async validateUniqueName() {
            debugger;
            if (!this.InfoData.UniqueName?.trim()) {
                this.isUniqueNameValid = null;
                this.uniqueNameError = '';
                return;
            }

            this.uniqueNameCheckLoading = true;
            this.uniqueNameError = '';

            try {

                const payload = {
                    "uniqueName": this.InfoData.UniqueName.trim(),
                    "relatedInfoId": this.InfoData.RelatedInfoId || 0
                };

                const response = await DataService.CheckUniqueName(payload);

                this.isUniqueNameValid = response.data.isUnique;
                this.uniqueNameError = response.data.isUnique
                    ? ''
                    : 'Unique Name already exists';
                const conflicts = Array.isArray(response.data.conflicts) ? response.data.conflicts : [response.data.conflicts];

                if (conflicts.length > 0) {
                    // Map each conflict to a descriptive message
                    const messages = conflicts.map(item => {
                        const { catalogue_Name, location_Name, unique_Name } = item;
                        return `Unique Name "${unique_Name}" already exists for "${catalogue_Name}" at  location "${location_Name}"`;
                    });

                    // Combine all messages into one
                    const conflictMessage = `Duplicity Error: ${messages.join('; ')}. Use a different name`;

                    // Show the error alert
                    this.ShowAlert(conflictMessage, "error", this.$t("Alert"));

                    // Optionally clear the input
                    this.InfoData.UniqueName = '';
                    return false
                }


            } catch (error) {
                this.isUniqueNameValid = false;
                this.uniqueNameError = 'Error checking uniqueness. Please try again.';
                console.error('UniqueName validation error:', error);
            } finally {
                this.uniqueNameCheckLoading = false;
            }
        },

        // Clear validation on focus
        clearUniqueNameValidation() {
            this.uniqueNameError = '';
            if (this.InfoData.UniqueName?.trim()) {
                this.isUniqueNameValid = null; // Reset to re-validate
            }
        }

    }
}

